// TensorRT for RTX: compiled once per SDK version (TRT_RTX_MINOR = 7, 8, ...), each copy against that version's
// headers (trt_rtx_sdk.h, generated by CMake, names them by absolute path). The SDK reuses the full TensorRT's header
// names, its nvinfer1 namespace and its entry-point names, so here they're renamed (nvinfer1 -> nvinfer1_rtx8) and the
// DLL's entry points are taken with GetProcAddress (trt_loader keeps it loaded), never linked: no symbol is shared
// with the full TensorRT or with another version's copy.
#include "trt_rtx_sdk.h"

#define RTX_CAT2(a, b) a##_rtx##b
#define RTX_CAT(a, b) RTX_CAT2(a, b)
#define nvinfer1 RTX_CAT(nvinfer1, TRT_RTX_MINOR)
#define nvonnxparser RTX_CAT(nvonnxparser, TRT_RTX_MINOR)
#include TRT_RTX_NVINFER
#include TRT_RTX_ONNXPARSER

#include <cstdio>
#include <filesystem>
#include <fstream>
#include <vector>

#include "rtx_backend.h"
#include "trt_loader.h"

#ifdef _WIN32
#include <windows.h>
#endif

static_assert(NV_TENSORRT_MAJOR == 1 && NV_TENSORRT_MINOR == TRT_RTX_MINOR, "headers of another TensorRT for RTX version");

int RTX_CAT(trt_rtx_header_version, TRT_RTX_MINOR)() { return NV_TENSORRT_VERSION; }

namespace {
namespace fs = std::filesystem;
using namespace nvinfer1;

struct Logger : ILogger {
    void log(Severity s, const char* msg) noexcept override {
        if (s <= Severity::kWARNING) fprintf(stderr, "[tensorrt-rtx] %s\n", msg);
    }
} logger;

std::vector<char> read_file(const fs::path& p) {
    std::ifstream f(p, std::ios::binary);
    return {std::istreambuf_iterator<char>(f), {}};
}

// the DLL's own entry points (the headers' inline createInferBuilder() etc. would link them by name)
template <class F>
F entry(void* module, const char* name) {
#ifdef _WIN32
    return module ? (F)GetProcAddress((HMODULE)module, name) : nullptr;
#else
    (void)module, (void)name;
    return nullptr;
#endif
}

class PixelFlowRtx final : public RtxEngine {
public:
    bool open(const std::string& onnx, const std::string& plan_path, int w, int h, int s, bool use_plan = true) {
        using MakeObj = void* (*)(void*, int32_t);
        using MakeParser = void* (*)(void*, void*, int);
        auto make_builder = entry<MakeObj>(rtx_module(), "createInferBuilder_INTERNAL");
        auto make_runtime = entry<MakeObj>(rtx_module(), "createInferRuntime_INTERNAL");
        auto make_parser = entry<MakeParser>(rtx_parser_module(), "createNvOnnxParser_INTERNAL");
        if (!make_builder || !make_runtime || !make_parser) return fprintf(stderr, "vsr: TensorRT for RTX isn't loaded\n"), false;
        plan_path_ = plan_path, cache_path_ = plan_path + ".jit";
        std::error_code ec;
        const fs::path plan_file = fs::u8path(plan_path), onnx_file = fs::u8path(onnx);
        const bool cached = use_plan && fs::exists(plan_file, ec) && fs::last_write_time(plan_file, ec) >= fs::last_write_time(onnx_file, ec);
        std::vector<char> plan;
        if (cached) plan = read_file(plan_file);
        else {
            fprintf(stderr, "vsr: building the TensorRT for RTX engine for %dx%d (a few seconds, first time only)\n", w, h);
            std::unique_ptr<IBuilder> b((IBuilder*)make_builder(&logger, NV_TENSORRT_VERSION));
            if (!b) return false;
            std::unique_ptr<INetworkDefinition> net(b->createNetworkV2(0));  // strongly typed: the fp16 ONNX decides
            std::unique_ptr<nvonnxparser::IParser> parser(
                (nvonnxparser::IParser*)make_parser(net.get(), &logger, NV_ONNX_PARSER_VERSION));
            if (!parser || !parser->parseFromFile(onnx_file.string().c_str(), (int)ILogger::Severity::kWARNING))
                return false;
            std::unique_ptr<IBuilderConfig> cfg(b->createBuilderConfig());
            IOptimizationProfile* prof = b->createOptimizationProfile();
            auto fix = [&](const char* name, int H, int W) {
                for (auto k : {OptProfileSelector::kMIN, OptProfileSelector::kOPT, OptProfileSelector::kMAX})
                    prof->setDimensions(name, k, Dims4{1, 3, H, W});
            };
            fix("cur", h, w), fix("prev", h, w), fix("prev_hr", h * s, w * s);
            cfg->addOptimizationProfile(prof);
            std::unique_ptr<IHostMemory> m(b->buildSerializedNetwork(*net, *cfg));
            if (!m) return false;
            plan.assign((char*)m->data(), (char*)m->data() + m->size());
            std::ofstream(plan_file, std::ios::binary).write(plan.data(), plan.size());
            fs::remove(fs::u8path(cache_path_), ec);  // its kernels belong to the old plan
        }
        runtime_.reset((IRuntime*)make_runtime(&logger, NV_TENSORRT_VERSION));
        if (!runtime_) return false;
        engine_.reset(runtime_->deserializeCudaEngine(plan.data(), plan.size()));
        if (!engine_) {
            if (!cached) return false;
            fprintf(stderr, "vsr: cached TensorRT for RTX engine is stale, rebuilding\n");
            return open(onnx, plan_path, w, h, s, false);
        }
        // its kernels are compiled for this GPU on first use; the runtime cache keeps them for the next start
        config_.reset(engine_->createRuntimeConfig());
        if (config_) {
            cache_.reset(config_->createRuntimeCache());
            if (cache_) {
                auto blob = read_file(fs::u8path(cache_path_));
                if (!blob.empty()) cache_->deserialize(blob.data(), blob.size());
                config_->setRuntimeCache(*cache_);
            }
        }
        ctx_.reset(config_ ? engine_->createExecutionContext(config_.get()) : engine_->createExecutionContext());
        return ctx_ && ctx_->setInputShape("cur", Dims4{1, 3, h, w}) && ctx_->setInputShape("prev", Dims4{1, 3, h, w}) &&
               ctx_->setInputShape("prev_hr", Dims4{1, 3, h * s, w * s});
    }

    bool infer(const void* cur, const void* prev, const void* prev_hr, void* out, void* stream) override {
        ctx_->setTensorAddress("cur", const_cast<void*>(cur));
        ctx_->setTensorAddress("prev", const_cast<void*>(prev));
        ctx_->setTensorAddress("prev_hr", const_cast<void*>(prev_hr));
        ctx_->setTensorAddress("hr", out);
        return ctx_->enqueueV3((cudaStream_t)stream);
    }

    void save_cache() override {
        if (!cache_) return;
        std::unique_ptr<IHostMemory> m(cache_->serialize());
        if (m && m->size()) {
            const fs::path p = fs::u8path(cache_path_), tmp = fs::u8path(cache_path_ + ".tmp");
            std::ofstream(tmp, std::ios::binary).write((const char*)m->data(), m->size());
            std::error_code ec;
            fs::rename(tmp, p, ec);
        }
    }

    ~PixelFlowRtx() override {  // in the reverse order of creation, as TensorRT wants
        save_cache();
        ctx_.reset(), cache_.reset(), config_.reset(), engine_.reset(), runtime_.reset();
    }

private:
    std::string plan_path_, cache_path_;
    std::unique_ptr<IRuntime> runtime_;
    std::unique_ptr<ICudaEngine> engine_;
    std::unique_ptr<IRuntimeConfig> config_;
    std::unique_ptr<IRuntimeCache> cache_;
    std::unique_ptr<IExecutionContext> ctx_;
};
}  // namespace

std::unique_ptr<RtxEngine> RTX_CAT(make_rtx_engine, TRT_RTX_MINOR)(const std::string& onnx, const std::string& plan_path,
                                                                   int w, int h, int scale) {
    auto e = std::make_unique<PixelFlowRtx>();
    if (!e->open(onnx, plan_path, w, h, scale)) return nullptr;
    return e;
}
